 .size(140.dp)
 .width(100.dp)
 )

 if (uiState.isLoading) {
 CircularProgressIndicator(modifier = Modifier.align(Alignment.Center))
 } else {
 // Todo el contenido y botones ahora está en la misma columna scrolleable.
 Column(
