 val isIncorrectSelection = isSelected && !isCorrectAns && showFeedback
 val shouldHighlightCorrect =
 showFeedback && isCorrectAns && selectedAnswerIndex != null && !isSelected && !shuffledAnswers[selectedAnswerIndex!!].isCorrect
