@Composable
fun formatTime(ms: Long): String {
 if (ms < 0) return "00:00"
 val totalSeconds = ms / 1000
 val minutes = (totalSeconds / 60).toInt()
 val seconds = (totalSeconds % 60).toInt()
 return "%02d:%02d".format(minutes, seconds)
}

